async function tgCallRetry(token, method, payload, attempts = 4) {
  let last=null;
  for(let i=0;i<attempts;i++){
    try{
      const r=await fetch(`https://api.telegram.org/bot${token}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});
      const j=await r.json().catch(()=>({}));
      if(r.ok&&j.ok)return {ok:true};
      const retry=Number(j?.parameters?.retry_after||0), transient=r.status===429||r.status>=500;
      last={ok:false,status:r.status,error:j?.description||`Telegram HTTP ${r.status}`};
      if(!transient)return last;
      await sleep(Math.min(12000,Math.max(700,(retry*1000)||700*(i+1))));
    }catch(e){
      last={ok:false,status:0,error:String(e?.message||e)};
      if(i<attempts-1) await sleep(Math.min(2500,450*(i+1)));
    }
  }
  return last||{ok:false,status:0,error:"Telegram error"};
}
async function ensureBroadcastJob(db, updateId){
  let job=await db.prepare("SELECT * FROM p01_broadcast_jobs WHERE id=?").bind(updateId).first();
  if(!job){
    await db.prepare("INSERT OR IGNORE INTO p01_broadcast_jobs (id,update_id,cursor,last_bot_id,last_chat_id,sent,failed,done,last_error,lease_until,lease_token,updated_at) VALUES (?,?,0,'','',0,0,0,'',0,'',?)").bind(updateId,updateId,Date.now()).run();
    job=await db.prepare("SELECT * FROM p01_broadcast_jobs WHERE id=?").bind(updateId).first();
  }
  return job;
}
async function sendTelegramBatch(rows, text, reply_markup){
  const out=[];
  for(let i=0;i<rows.length;i+=4){
    const chunk=rows.slice(i,i+4);
    const res=await Promise.all(chunk.map(r=>tgCallRetry(r.token,"sendMessage",{chat_id:r.chat_id,text,reply_markup})));
    out.push(...res);
  }
  return out;
}
async function broadcastWorkerUpdate(db, updateId, version, maxPerRun = 8) {
  let job=await ensureBroadcastJob(db,updateId);
  if(Number(job?.done)===1)return {sent:Number(job.sent||0),failed:Number(job.failed||0),done:true,cursor:Number(job.cursor||0),busy:false,last_error:job.last_error||""};
  const now=Date.now(), leaseToken=randHex(12), leaseUntil=now+25000;
  const claim=await db.prepare("UPDATE p01_broadcast_jobs SET lease_until=?,lease_token=?,updated_at=? WHERE id=? AND done=0 AND (lease_until IS NULL OR lease_until<?)").bind(leaseUntil,leaseToken,now,updateId,now).run();
  if(!Number(claim?.meta?.changes||0)){
    job=await ensureBroadcastJob(db,updateId);
    return {sent:Number(job?.sent||0),failed:Number(job?.failed||0),done:Number(job?.done||0)===1,cursor:Number(job?.cursor||0),busy:true,last_error:job?.last_error||""};
  }
  try {
    job=await db.prepare("SELECT * FROM p01_broadcast_jobs WHERE id=?").bind(updateId).first();
    const lastBot=String(job.last_bot_id||""),lastChat=String(job.last_chat_id||"");
    const rows=(await db.prepare(`SELECT u.bot_id,u.chat_id,b.token FROM p01_tg_users u JOIN p01_bots b ON b.id=u.bot_id WHERE b.enabled=1 AND (u.bot_id>? OR (u.bot_id=? AND u.chat_id>?)) ORDER BY u.bot_id ASC,u.chat_id ASC LIMIT ?`).bind(lastBot,lastBot,lastChat,maxPerRun).all()).results||[];
    const reply_markup={inline_keyboard:[[{text:"بروزرسانی و نصب",callback_data:`worker:apply:${updateId}`,style:"success"}]]};
    const text=`🚀 نسخه جدید Worker آماده شد${version?` — ${version}`:""}\nبرای نصب، دکمه «بروزرسانی و نصب» را بزن.`;
    const results=await sendTelegramBatch(rows,text,reply_markup);
    let sent=Number(job.sent||0),failed=Number(job.failed||0),cursor=Number(job.cursor||0),newLastBot=lastBot,newLastChat=lastChat;
    let lastError="";
    for(let i=0;i<rows.length;i++){
      const x=results[i],r=rows[i];
      newLastBot=String(r.bot_id);newLastChat=String(r.chat_id);cursor++;
      if(x.ok) sent++; else { failed++; lastError=String(x.error||"Telegram error").slice(0,300); }
    }
    const done=rows.length<maxPerRun;
    await db.prepare("UPDATE p01_broadcast_jobs SET cursor=?,last_bot_id=?,last_chat_id=?,sent=?,failed=?,done=?,last_error=?,lease_until=0,lease_token='',updated_at=? WHERE id=? AND lease_token=?").bind(cursor,newLastBot,newLastChat,sent,failed,done?1:0,lastError,Date.now(),updateId,leaseToken).run();
    return {sent,failed,done,cursor,busy:false,last_error:lastError};
  } catch(e) {
    await db.prepare("UPDATE p01_broadcast_jobs SET last_error=?,lease_until=0,lease_token='',updated_at=? WHERE id=? AND lease_token=?").bind(String(e?.message||e).slice(0,300),Date.now(),updateId,leaseToken).run().catch(()=>{});
    throw e;
  }
}
async function getBroadcastStatus(db, updateId){
  const job=await db.prepare("SELECT sent,failed,done,cursor,last_error,updated_at FROM p01_broadcast_jobs WHERE id=?").bind(updateId).first();
  if(!job) return {sent:0,failed:0,done:false,cursor:0,last_error:"",updated_at:0};
  return {sent:Number(job.sent||0),failed:Number(job.failed||0),done:Number(job.done||0)===1,cursor:Number(job.cursor||0),last_error:String(job.last_error||""),updated_at:Number(job.updated_at||0)};
}
