// ------------------------------------------------------------------ Auth (KV + D1)
async function hashPassword(pw, salt) {
  const key = await crypto.subtle.importKey("raw", enc.encode(pw), "PBKDF2", false, ["deriveBits"]);
  return bufToHex(await crypto.subtle.deriveBits({ name: "PBKDF2", salt: enc.encode(salt), iterations: 100000, hash: "SHA-256" }, key, 256));
}
async function sessionCreate(env) {
  const t = randHex(32);
  if (env.KV) await env.KV.put("s:" + t, "1", { expirationTtl: APP.sessionTtl });
  else await env.DB.prepare("INSERT INTO p01_sessions (token,expires_at) VALUES (?,?)").bind(t, Date.now() + APP.sessionTtl * 1000).run();
  return t;
}
async function sessionValid(env, t) {
  if (!t || !/^[a-f0-9]{64}$/.test(t)) return false;
  if (env.KV) return (await env.KV.get("s:" + t)) !== null;
  const r = await env.DB.prepare("SELECT expires_at FROM p01_sessions WHERE token=?").bind(t).first();
  return !!r && r.expires_at > Date.now();
}
async function sessionDelete(env, t) {
  if (!t) return;
  if (env.KV) await env.KV.delete("s:" + t);
  else await env.DB.prepare("DELETE FROM p01_sessions WHERE token=?").bind(t).run();
}
const getCookie = (req, n) => { const m = (req.headers.get("Cookie") || "").match(new RegExp("(?:^|; )" + n + "=([^;]+)")); return m ? m[1] : null; };
const cookieHdr = (v, age) => `${APP.cookie}=${v}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`;
const isAuthed = (req, env) => sessionValid(env, getCookie(req, APP.cookie));
async function checkPassword(env, pw) {
  pw = String(pw || "");
  const salt = await getSetting(env.DB, "pw_salt"), h = await getSetting(env.DB, "pw_hash");
  if (salt && h) return (await hashPassword(pw, salt)) === h;
  return pw === (env.ADMIN_PASSWORD || APP.defaultPassword);
}
