async function ensureBotDb(db, botId) { let r=await db.prepare("SELECT * FROM p01_bot_db WHERE bot_id=?").bind(botId).first(); if(!r){await db.prepare("INSERT INTO p01_bot_db (bot_id,enabled,secret,created_at,updated_at) VALUES (?,?,?,?,?)").bind(botId,0,randHex(24),Date.now(),Date.now()).run(); r=await db.prepare("SELECT * FROM p01_bot_db WHERE bot_id=?").bind(botId).first();} return r; }

async function ensureBotWebhook(db, bot, host) {
  if (!bot?.token || !host) return;
  const markerKey = `webhook_host_${bot.id}`;
  const knownHost = await getSetting(db, markerKey, "");
  if (knownHost === host && bot.secret) return;
  const secret = String(bot.secret || randHex(16));
  const webhook = `https://${host}/tg/hook`;
  try {
    const r = await (await fetch(`https://api.telegram.org/bot${bot.token}/setWebhook`, {
      method:"POST", headers:{"content-type":"application/json"},
      body:JSON.stringify({url:webhook,secret_token:secret,drop_pending_updates:false,allowed_updates:["message","callback_query"]})
    })).json();
    if (!r?.ok) return;
    await db.batch([
      db.prepare("UPDATE p01_bots SET secret=? WHERE id=?").bind(secret,bot.id),
      db.prepare("INSERT INTO p01_settings (k,v) VALUES (?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v").bind(markerKey,host)
    ]);
  } catch (_) {}
}

async function initializePrivilegedBots(db, requestHost="") {
  // Bootstrap privileged bots at most once per minute per Worker isolate.
  // This avoids a Telegram API round-trip on every panel/API request while still self-healing.
  if (Date.now() - PRIV_BOTS_AT < 60_000) return;
  PRIV_BOTS_AT = Date.now();
  // Mark the configured registration bot and current panel bot without exposing tokens.
  try {
    const reg = await db.prepare("SELECT * FROM p01_bots WHERE lower(username)=lower(?) LIMIT 1").bind(SYSTEM_BOTS.registrationUsername).first();
    if (reg) {
      await db.prepare("UPDATE p01_bots SET is_registration=1 WHERE id=?").bind(reg.id).run();
      await setSetting(db,"registration_bot_id",reg.id);
      if (requestHost) await ensureBotWebhook(db,reg,requestHost);
    }
  } catch (_) {}

  try {
    const panelId = await getSetting(db,"panel_bot_id");
    if (panelId) await db.prepare("UPDATE p01_bots SET is_panel=1,panel_secret=COALESCE(panel_secret,?) WHERE id=?").bind(randHex(24),panelId).run();
  } catch (_) {}

  // دو ربات سیستمی (ادمین + ثبت‌نام): نقش هر توکن از روی getMe تعیین می‌شود
  for (const tk of [SYSTEM_BOTS.adminToken, SYSTEM_BOTS.registrationToken]) {
    if (!tk || !tk.includes(":")) continue;
    try {
      const me = await (await fetch(`https://api.telegram.org/bot${tk}/getMe`)).json().catch(()=>null);
      const uname = String(me?.result?.username || "");
      const lu = uname.toLowerCase();
      const isReg = lu === SYSTEM_BOTS.registrationUsername.toLowerCase();
      const isAdm = lu === SYSTEM_BOTS.adminUsername.toLowerCase();
      if (!me?.ok || (!isReg && !isAdm)) continue;
      let row = await db.prepare("SELECT * FROM p01_bots WHERE token=?").bind(tk).first();
      if (!row) row = await db.prepare("SELECT * FROM p01_bots WHERE lower(username)=lower(?) OR (?=1 AND is_admin=1) OR (?=1 AND is_registration=1) ORDER BY created_at LIMIT 1").bind(uname, isAdm?1:0, isReg?1:0).first();
      const adminChat = isAdm ? String(SYSTEM_BOTS.adminId) : (row?.admin_chat || null);
      if (row) {
        if (row.token !== tk) await db.prepare("DELETE FROM p01_settings WHERE k=?").bind(`webhook_host_${row.id}`).run();
        await db.prepare("UPDATE p01_bots SET token=?,username=?,is_admin=?,is_registration=?,enabled=COALESCE(enabled,1),claim_token=NULL,admin_chat=? WHERE id=?").bind(tk, uname, isAdm?1:0, isReg?1:0, adminChat, row.id).run();
      } else {
        await db.prepare("INSERT INTO p01_bots (id,token,username,secret,enabled,created_at,last_seen,claim_token,admin_chat,is_admin,is_registration,is_panel,panel_secret) VALUES (?,?,?,?,1,?,0,NULL,?,?,?,0,?)").bind(crypto.randomUUID(), tk, uname, randHex(16), Date.now(), adminChat, isAdm?1:0, isReg?1:0, randHex(24)).run();
      }
      const fresh = await db.prepare("SELECT * FROM p01_bots WHERE token=?").bind(tk).first();
      if (fresh) {
        if (isAdm) { await setSetting(db,"admin_bot_id",fresh.id); await setSetting(db,"admin_bot_username",uname); }
        else await setSetting(db,"registration_bot_id",fresh.id);
        if (requestHost) await ensureBotWebhook(db,fresh,requestHost);
      }
    } catch (_) {}
  }
}

