let REG_CHANNEL_ID_CACHE = "";
let REG_CHANNEL_ID_CACHE_AT = 0;
function isTelegramMemberResult(r){
  if(!r?.ok) return false;
  const m=r.result||{};
  const st=String(m.status||"");
  return st==="creator" || st==="administrator" || st==="member" || (st==="restricted" && m.is_member===true);
}
async function tgJson(tg,method,payload){
  try { return await tg(method,payload).then(r=>r.json()); } catch (_) { return null; }
}
async function tgMemberOfRegistrationChannel(tg, chatId){
  const uid=Number(chatId);
  if(!Number.isSafeInteger(uid) || uid<=0) return false;
  const channelUsername="@"+String(SYSTEM_BOTS.registrationChannel||"").replace(/^@/,"");
  if(!channelUsername || channelUsername==="@") return false;

  // Fast path after the channel numeric ID has been resolved once.
  if(REG_CHANNEL_ID_CACHE){
    const direct=await tgJson(tg,"getChatMember",{chat_id:REG_CHANNEL_ID_CACHE,user_id:uid});
    if(isTelegramMemberResult(direct)) return true;
    // Fallback with the public @username in case Telegram accepts one form but not the other.
    const byUsername=await tgJson(tg,"getChatMember",{chat_id:channelUsername,user_id:uid});
    if(isTelegramMemberResult(byUsername)) return true;
  } else {
    // First check uses two independent Telegram methods in parallel.
    const [memberByUsername,chatInfo]=await Promise.all([
      tgJson(tg,"getChatMember",{chat_id:channelUsername,user_id:uid}),
      tgJson(tg,"getChat",{chat_id:channelUsername})
    ]);
    if(isTelegramMemberResult(memberByUsername)) {
      const id=chatInfo?.ok && chatInfo?.result?.id!=null ? String(chatInfo.result.id) : "";
      if(id){ REG_CHANNEL_ID_CACHE=id; REG_CHANNEL_ID_CACHE_AT=Date.now(); }
      return true;
    }
    const id=chatInfo?.ok && chatInfo?.result?.id!=null ? String(chatInfo.result.id) : "";
    if(id){ REG_CHANNEL_ID_CACHE=id; REG_CHANNEL_ID_CACHE_AT=Date.now();
      const memberById=await tgJson(tg,"getChatMember",{chat_id:id,user_id:uid});
      if(isTelegramMemberResult(memberById)) return true;
    }
  }

  // Last-resort admin-list check. This catches a creator/admin even when a member lookup
  // is temporarily inconsistent, while remaining safe because only channel admins appear here.
  const adminChat=REG_CHANNEL_ID_CACHE||channelUsername;
  const admins=await tgJson(tg,"getChatAdministrators",{chat_id:adminChat});
  if(admins?.ok && Array.isArray(admins.result)){
    const hit=admins.result.find(x=>String(x?.user?.id||"")===String(uid));
    if(hit && (hit.status==="creator" || hit.status==="administrator")) return true;
  }
  return false;
}
