async function warpRegister() {
  // Cloudflare's runtime supports these operations, but the dashboard's JS/TS
  // type checker may not include the X25519 overloads in its current lib.dom
  // declarations. Keep the runtime calls unchanged while narrowing the editor
  // boundary to `any` so it cannot produce the 4 false-positive type errors.
  /** @type {any} */
  const subtleAny = crypto.subtle;
  const kp = await subtleAny.generateKey({ name: "X25519" }, true, ["deriveBits"]);
  const pub = new Uint8Array(await subtleAny.exportKey("raw", kp.publicKey));
  const priv = new Uint8Array(await subtleAny.exportKey("pkcs8", kp.privateKey)).slice(-32);
  const r = await fetch("https://api.cloudflareclient.com/v0a4005/reg", {
    method: "POST", headers: { "content-type": "application/json", "user-agent": "okhttp/3.12.1", "cf-client-version": "a-6.30-3596" },
    body: JSON.stringify({ key: b64u8(pub), install_id: "", fcm_token: "", tos: new Date().toISOString(), type: "Android", model: "PC", locale: "en_US" }),
  });
  const cf = (await r.json()).config;
  return { priv: b64u8(priv), peerPub: cf.peers[0].public_key, v4: cf.interface.addresses.v4, v6: cf.interface.addresses.v6, reserved: [...Uint8Array.from(atob(cf.client_id), (ch) => ch.charCodeAt(0))], endpoint: "engage.cloudflareclient.com", port: 2408 };
}

