async function cfGetContent(token, accountId, script) {
  const base = "https://api.cloudflare.com/client/v4/accounts/" + accountId + "/workers/scripts/" + encodeURIComponent(script);
  const headers = { Authorization: "Bearer " + token, Accept: "*/*" };
  for (const u of [base + "/content/v2", base + "/content", base]) {
    try {
      const r = await fetch(u, { headers });
      if (!r.ok) continue;
      if ((r.headers.get("content-type") || "").toLowerCase().includes("multipart/")) {
        // خروجی multipart را باز می‌کنیم تا هدرها داخل کد Worker نروند
        let best = null;
        for (const [k, v] of (await r.formData()).entries()) {
          const t = typeof v === "string" ? v : await v.text();
          if (cfCodeOk(t) && (k === "worker.js" || !best)) best = t;
        }
        if (best) return best.replace(/^\uFEFF/, "");
        continue;
      }
      let t = (await r.text()).replace(/^\uFEFF/, "");
      if (t.trimStart().startsWith("{") && t.includes('"result"')) { try { const z = JSON.parse(t).result; t = typeof z === "string" ? z : (z && (z.script || z.content)) || ""; } catch (_) { continue; } }
      if (cfCodeOk(t)) return t;
    } catch (_) {}
  }
  throw new Error("کد Worker فعلی قابل دریافت نبود؛ دسترسی Workers Scripts: Edit را بده یا از بخش آپدیت استفاده کن");
}

async function cfDeploy(token, accountId, script, code, d1Id, kvId) {
  if (!cfCodeOk(code)) throw new Error("کد Worker نامعتبر است (فایل خراب یا ناقص)");
  const existing = await cfGetBindings(token, accountId, script);
  if (!Array.isArray(existing)) throw new Error("خواندن Bindingهای Worker از Cloudflare ناموفق بود؛ برای جلوگیری از قطع شدن دیتابیس، آپدیت انجام نشد. چند ثانیه بعد دوباره امتحان کن");
  const mergedB = mergeBindings(existing, d1Id, kvId);
  if (!mergedB.some((b) => b.type === "d1" && b.name === "DB")) throw new Error("شناسه دیتابیس D1 پیدا نشد؛ برای جلوگیری از حذف اطلاعات، آپدیت انجام نشد");
  let flags = [];
  try { flags = ((await cfFetch(token, "/accounts/" + accountId + "/workers/scripts/" + encodeURIComponent(script) + "/settings")).result || {}).compatibility_flags || []; } catch (_) {}
  const metadata = {
    main_module: "worker.js",
    compatibility_date: "2026-10-01",
    bindings: mergedB,
  };
  if (flags.length) metadata.compatibility_flags = flags;
  const form = new FormData();
  form.set("metadata", new Blob([JSON.stringify(metadata)], { type: "application/json" }));
  form.set("worker.js", new Blob([code], { type: "application/javascript+module" }));
  const out = await cfFetch(
    token,
    "/accounts/" + accountId + "/workers/scripts/" + encodeURIComponent(script),
    { method: "PUT", body: form }
  );
  try {
    await cfFetch(token, "/accounts/" + accountId + "/workers/scripts/" + encodeURIComponent(script) + "/subdomain", {
      method: "POST",
      body: JSON.stringify({ enabled: true }),
    });
  } catch (_) {}
  return out;
}
