async function runCfDeployCode(env, code, request) {
  const db = env.DB;
  const cf = await loadCf(db);
  if (!cf.token) throw new Error("اول Cloudflare API را وصل کن (منوی API)");
  if (!cf.accountId) throw new Error("Account ID ذخیره نشده — یک‌بار از منوی API اتصال را کامل کن");
  code = String(code || "").replace(/^﻿/, "").trimStart();
  if (!code || !code.includes("export default")) throw new Error("فایل worker.js معتبر نیست");
  const host = request ? new URL(request.url).host : "";
  const prefer = cf.script || host;
  const info = await cfEnsure(cf.token, cf.accountId, host, cf.script, { d1: cf.d1, kv: cf.kv });
  if (cf.script) info.script = cf.script;
  await cfDeploy(cf.token, info.accountId, info.script, code, info.d1Id || cf.d1, info.kvId || cf.kv);
  const vm = code.match(/version\s*:\s*["\']([^"\']+)["\']/);
  // بعد از دپلوی، کد زنده را از Cloudflare می‌خوانیم و مطمئن می‌شویم واقعاً عوض شده
  let verify = { id: "verify", ok: true, detail: "نصب انجام شد (تأیید کد زنده ممکن نبود)" };
  for (let i = 0; i < 3; i++) {
    try {
      const live = await cfGetContent(cf.token, info.accountId, info.script);
      const norm = (x) => String(x).replace(/\r\n/g, "\n").trim();
      const lv = (live.match(/version\s*:\s*["\']([^"\']+)["\']/) || [])[1];
      if (await sha256Hex(enc.encode(norm(live))) === await sha256Hex(enc.encode(norm(code)))) { verify = { id: "verify", ok: true, detail: "کد زنده روی Cloudflare با نسخه جدید یکی است ✓" }; break; }
      if (vm && lv && lv !== vm[1]) { if (i === 2) throw new Error("Cloudflare هنوز نسخه قبلی را نشان می‌دهد (" + lv + ")؛ چند ثانیه بعد دوباره امتحان کن"); await sleep(1500); continue; }
      verify = { id: "verify", ok: true, detail: "نسخه " + (lv || "جدید") + " روی Cloudflare فعال است ✓" }; break;
    } catch (e) { if (String(e?.message || "").startsWith("Cloudflare هنوز")) throw e; break; }
  }
  if (vm) await setSetting(db, "latest_version", vm[1]);
  await saveCf(db, info, cf.token);
  await cfMirrorPut(env, { token: cf.token, accountId: info.accountId, script: info.script, d1: info.d1Id || cf.d1, kv: info.kvId || cf.kv });
  await notify(db, "green", "ورکر با موفقیت آپدیت شد", info.script);
  return { ok: true, script: info.script, steps: (info.steps||[]).concat([{ id: "replace", ok: true, detail: "Worker قبلی با نسخه جدید جایگزین شد" }, { id: "deploy", ok: true, detail: "کد جدید روی Cloudflare آپلود شد" }, verify]) };
}

