const publicCfg = (c, ips = 0) => ({
  id: c.id, name: c.name, protocol: c.protocol, live: PROTOS[c.protocol]?.live || false, note: c.note || "",
  volume_limit: c.volume_limit, volume_used: c.volume_used, expire_at: c.expire_at, days: c.days, start_first: !!c.start_first,
  ip_limit: c.ip_limit, ips, enabled: !!c.enabled, created_at: c.created_at, last_online: c.last_online, status: statusOf(c), extra: (() => { try { const x = JSON.parse(c.extra || "{}"); return { addr: x.addr || "", host: x.host || "", port: x.port || "", tls: x.tls !== false, sni: x.sni || "", fp: x.fp || "chrome", speed: x.speed || "fast", server: x.server || "" }; } catch { return {}; } })(),
});
const UB = { MB: 1048576, GB: 1073741824, TB: 1099511627776 };
const unitBytes = (n, u) => Math.max(0, Math.round(Number(n || 0) * (UB[u] || UB.GB)));
const unitDays = (n, u) => Math.max(0, Math.round(Number(n || 0) * (u === "ماه" ? 30 : u === "سال" ? 365 : 1)));
