async function createConfig(db, b, prefix, idx) {
  const proto = PROTOS[b.protocol] ? b.protocol : null;
  if (!proto) throw new Error("پروتکل نامعتبر است");
  const id = crypto.randomUUID();
  let name = String(b.name || "").trim().slice(0, 40) || genName(prefix);
  if (idx > 0) name = `${name}_${idx + 1}`;
  const days = unitDays(b.days, b.daysUnit), x = {};
  if (!PROTOS[proto].live) throw new Error("فقط پروتکل‌های قابل اجرای مستقیم روی Cloudflare Worker مجاز هستند");
  if (b.addr) x.addr = parseList(b.addr).join("\n");
  if (b.host) x.host = String(b.host).trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "").slice(0, 120);
  if (b.port) x.port = parseInt(b.port) || undefined;
  if (b.tls === false) x.tls = false;
  if (b.sni) x.sni = String(b.sni).trim().slice(0, 120);
  if (b.fp && b.fp !== "chrome") x.fp = String(b.fp).slice(0, 20);
  if (b.speed && ["balanced","fast","stable"].includes(String(b.speed))) x.speed = String(b.speed);
  const startFirst = b.startFirst && days ? 1 : 0;
  await db.prepare(`INSERT INTO p01_configs (id,name,protocol,volume_limit,volume_used,expire_at,days,start_first,ip_limit,enabled,note,extra,created_at,last_online)
    VALUES (?,?,?,?,0,?,?,?,?,1,?,?,?,0)`).bind(id, name, proto, unitBytes(b.volume, b.volumeUnit), days && !startFirst ? Date.now() + days * 86400000 : 0, days, startFirst,
    Math.max(0, parseInt(b.ipLimit) || 0), String(b.note || "").slice(0, 200), JSON.stringify(x), Date.now()).run();
  return id;
}

