    const chart=await Promise.all(chartTimes.map(async(t)=>{const day=dayKey(t),r=await db.prepare("SELECT bytes FROM p01_usage WHERE day=?").bind(day).first();return{day,dow:new Date(t).getUTCDay(),bytes:r?r.bytes:0};}));
    const sm=new Map((settingsR.results||[]).map(r=>[r.k,r.v]));
    if(!sm.get("cf_token")){ const mm=await cfMirrorRestore(env,db); if(mm){ sm.set("cf_token",mm.token); if(mm.accountId)sm.set("cf_account",mm.accountId); if(mm.script)sm.set("cf_script",mm.script); if(mm.d1)sm.set("cf_d1",mm.d1); if(mm.kv)sm.set("cf_kv",mm.kv); } }
    const S=(k,d="")=>sm.has(k)?sm.get(k):d;
