    const me = await (await fetch(`https://api.telegram.org/bot${token}/getMe`)).json().catch(() => null);
    if (!me || !me.ok) return json({ error: "توکن نامعتبر است" }, 400);
    const existing = await db.prepare("SELECT * FROM p01_bots WHERE token=?").bind(token).first();
    const id = existing?.id || crypto.randomUUID(), secret = String(existing?.secret||randHex(16)), host = (await getSetting(db, "domain")) || url.host;
    const protectedAdmin = String(token) === String(SYSTEM_BOTS.adminToken || "");
    const protectedRegistration = String((me.result.username || "")).replace(/^@/, "").toLowerCase() === String(SYSTEM_BOTS.registrationUsername || "").replace(/^@/, "").toLowerCase();
    const isAdmin = protectedAdmin || Number(existing?.is_admin||0)===1;
    const isRegistration = protectedRegistration || Number(existing?.is_registration||0)===1;
    const isPanel = String(kind)==="panel" && !isAdmin && !isRegistration;
    const claimToken = (isAdmin || isRegistration) ? null : randHex(18);
    const wh = await (await fetch(`https://api.telegram.org/bot${token}/setWebhook`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ url: `https://${host}/tg/hook`, secret_token: secret, drop_pending_updates: true, allowed_updates:["message","callback_query"] }) })).json();
    if (!wh.ok) return json({ error: "ثبت وب‌هوک ناموفق بود" }, 400);
    if(isPanel) await db.prepare("UPDATE p01_bots SET is_panel=0 WHERE id<>?").bind(id).run();
    if(isRegistration) await db.prepare("UPDATE p01_bots SET is_registration=0 WHERE id<>?").bind(id).run();
    await db.prepare("INSERT INTO p01_bots (id,token,username,secret,enabled,created_at,last_seen,claim_token,admin_chat,is_admin,is_registration,is_panel,panel_secret) VALUES (?,?,?,?,1,?,0,?,?,?, ?,?,?) ON CONFLICT(token) DO UPDATE SET username=excluded.username,secret=excluded.secret,enabled=1,claim_token=excluded.claim_token,is_admin=excluded.is_admin,is_registration=excluded.is_registration,is_panel=excluded.is_panel,panel_secret=COALESCE(p01_bots.panel_secret,excluded.panel_secret)")
      .bind(id, token, me.result.username || "", secret, Date.now(), claimToken, existing?.admin_chat||null, isAdmin?1:0, isRegistration?1:0, isPanel?1:0, existing?.panel_secret||randHex(24)).run();
    if(isPanel) await setSetting(db, "panel_bot_id", id);
    if(isRegistration) await setSetting(db, "registration_bot_id", id);
    if(isAdmin) { await setSetting(db,"admin_bot_id",id); await setSetting(db,"admin_bot_username",me.result.username||""); }
