    if (data === "m:mybot") { const bd=await ensureBotDb(db,bot.id); return edit(cq.message.message_id, "<b>ربات خودم</b>\nتوکن ربات در پنل وب و جدا از فایل گرفته می‌شود.\nJS و PY اجرا می‌شوند؛ ZIP اگر worker.js یا main.py داشته باشد Deploy می‌شود.\nدیتابیس: <b>"+(bd.enabled?"روشن":"خاموش")+"</b>\nلینک DB: <code>"+esc(`${new URL(request.url).origin}/bot-db/${bot.id}/${bd.secret}`)+"</code>", {reply_markup:kb([[G("📁 فایل‌ها و ترکیب","mf:home")],[B("باز کردن پنل ربات","m:panel")],[bd.enabled?D("خاموش کردن DB","mydb:toggle"):G("وصل کردن DB","mydb:toggle")],[B("بازگشت","m:home")]]) }); }
    if (data === "mydb:toggle") { const bd=await ensureBotDb(db,bot.id); const en=bd.enabled?0:1; await db.prepare("UPDATE p01_bot_db SET enabled=?,updated_at=? WHERE bot_id=?").bind(en,Date.now(),bot.id).run(); return edit(cq.message.message_id,`اتصال دیتابیس ${en?"روشن":"خاموش"} شد.`,{reply_markup:home()}); }
        if (data === "m:settings") return edit(cq.message.message_id, "<b>تنظیمات ربات</b>\n1. این چت مدیر فعلی است.\n2. رمز پنل از ربات درخواست نمی شود.\n3. خطاهای سطح قرمز به مدیر ارسال می شوند.", { reply_markup:kb([[B("ثبت این چت به عنوان مدیر","settings:claimhere")],[B("بازگشت","m:home")]]) });
