      if(op==="toggle"){await db.prepare("UPDATE p01_configs SET enabled=? WHERE id=?").bind(c.enabled?0:1,id).run(); const n=await cfgRow(id); return edit(cq.message.message_id,`وضعیت ${esc(n.name)}: <b>${statusText(n)}</b>`,{reply_markup:configActions(id,!!n.enabled)});}
      if(op==="delete"){await db.batch([db.prepare("DELETE FROM p01_configs WHERE id=?").bind(id),db.prepare("DELETE FROM p01_ips WHERE cid=?").bind(id)]); return edit(cq.message.message_id,"کانفیگ حذف شد.",{reply_markup:home()});}
