      if(op==="clone"){const nid=await createConfig(db,{protocol:c.protocol,name:c.name+"-copy",volume:c.volume_limit/1073741824,volumeUnit:"GB",days:c.expire_at?Math.max(0,Math.ceil((c.expire_at-Date.now())/86400000)):0,addr:JSON.parse(c.extra||"{}").addr,port:JSON.parse(c.extra||"{}").port},(await getSetting(db,"prefix"))||"Parham",0); return edit(cq.message.message_id,"یک کپی از کانفیگ ساخته شد.",{reply_markup:home()});}
