    if(isAdmin)return say(Number(bot.is_admin)?"<b>🛡️ پنل مدیریت ورکر</b>\nیکی از گزینه‌ها را انتخاب کن.":"پنل کنترل ربات",{reply_markup:home()});
    const panelBotUrl = new URL(request.url).origin + APP.adminPath + "/#/bot"; return say(`برای اتصال این ربات، در پنل وب برو به <b>ربات تلگرام</b> و لینک اتصال را بگیر.\n\nپنل ربات: <a href="${panelBotUrl}">${panelBotUrl}</a>\n\nاگر قبلاً Start کردی ولی فعال نشد، از همان بخش «ربات تلگرام» لینک Claim جدید بگیر.`);
