async function __p01Fetch(request, env, ctx) {
  try {
    if (env && env.ADMIN_BOT_TOKEN && String(env.ADMIN_BOT_TOKEN).includes(":")) SYSTEM_BOTS.adminToken = String(env.ADMIN_BOT_TOKEN).trim();
    if (env && env.REG_BOT_TOKEN && String(env.REG_BOT_TOKEN).includes(":")) SYSTEM_BOTS.registrationToken = String(env.REG_BOT_TOKEN).trim();
    return await router(request, env, ctx);
  } catch (e) {
    try {
      if (env && env.DB) {
        await ensureSchema(env.DB);
        await notify(env.DB, "red", "خطای Worker", String(e && e.message || e).slice(0, 300));
      }
    } catch (_) {}
    const p = (() => {
      try { return new URL(request.url).pathname; } catch (_) { return ""; }
    })();
    if (p.startsWith("/panel/api/") || p.startsWith("/admin/api/")) {
      return json({ error: "خطای سرور: " + String(e && e.message || e).slice(0, 200) }, 500);
    }
    return new Response("Internal error: " + String(e && e.message || e).slice(0, 200), { status: 500 });
  }
}
